"""Publish an explicit developer-docs and local-SDK allowlist; retain private evidence outside dist."""
from pathlib import Path
from html import escape
import json, re, shutil, subprocess, hashlib, tarfile, io, zipfile, gzip
R=Path(__file__).resolve().parents[1]
D=R/'dist'
PUB=R/'public-docs'; PUB.mkdir(exist_ok=True)
V='0.1.0-preview.1'
RELEASE='ps-local-core-20261102.1'
GUIDELINES=json.loads((R/'developer/guidelines.json').read_text())
H=lambda x:escape(str(x),quote=True)
NAV=[('index.html','Overview'),('quickstart.html','Get started'),('human-stewardship.html','Human Stewardship'),('records.html','Records & corrections'),('boundaries.html','Authority & boundaries'),('continuity.html','Pause & recovery'),('journeys.html','Journey evidence'),('songwriter.html','Songwriter tools'),('localization.html','Language & meaning'),('api.html','Public reference API'),('status.html','Release & coverage')]
base=(R/'index.html').read_text()
header=re.search(r'<header class="site-header"[\s\S]*?</header>',base).group(0)
footer=re.search(r'<footer class="site-footer"[\s\S]*?</footer>',base).group(0)
header=header.replace('APIs &amp; SDKs','Developer docs').replace('APIs & SDKs','Developer docs')
footer=footer.replace('An exploratory developer resource. API and SDK examples are illustrative until verified.','Local tools, public reference APIs, and source-backed guidance. See the release scope before integrating.').replace('<div class="footer-links">','<div class="footer-links"><a href="/docs/quickstart.html">Get started</a><a href="/docs/human-stewardship.html">Human Stewardship Guidelines</a><a href="/docs/status.html">Release scope</a>')
def page(title,description,body,key='index.html',eyebrow='THE DEVELOPER LIBRARY'):
 nav=''.join(f'<li><a href="/docs/{p}"'+(' aria-current="page"' if p==key else '')+f'>{n}</a></li>' for p,n in NAV)
 canonical='https://promisestep.com/'+('playground.html' if key=='playground' else 'docs/'+key)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="description" content="{H(description)}"><meta name="theme-color" content="#f7f1e7"><meta name="robots" content="index,follow"><link rel="canonical" href="{canonical}"><link rel="icon" href="/art/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="/src/site.css"><link rel="stylesheet" href="/src/brand.css"><link rel="stylesheet" href="/developer/portal.css"><title>{H(title)} — PromiseStep</title><script type="module" src="/src/main.mjs"></script><script type="module" src="/developer/portal.mjs"></script></head><body><a class="skip-link" href="#main">Skip to content</a>{header}<main id="main"><div class="developer-header"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="standfirst">{description}</p></div><div class="doc-layout"><aside class="doc-nav" aria-label="Developer documentation"><details open><summary>Developer library</summary><ul>{nav}</ul><strong>A working example</strong><a href="/playground.html">Try correction & recovery →</a></details></aside><article class="doc-body">{body}</article></div></main>{footer}</body></html>'''
def code(text,id='sample'):
 return f'<button type="button" class="button secondary copy-code" data-copy-code="{id}">Copy example</button><pre><code id="{id}">{H(text.strip())}</code></pre>'
def card(title,desc,path,kicker=''):
 return f'<a class="doc-card" href="{path}"><p class="eyebrow">{kicker}</p><h3>{title}</h3><p>{desc}</p><span>Explore →</span></a>'
def notice(text):return f'<div class="notice"><p>{text}</p></div>'
articles={}
articles['index.html']=('A toolkit that earns its promises.','Start with a small working example. Understand its limits. Carry the work into your own application.',
'''<h2>The work stays with you.</h2><p>PromiseStep brings promises, records, boundaries, and continuity into a developer’s ordinary workflow. The local core runs in a supported browser or Node.js without a PromiseStep account or a live service. The public reference API carries the versioned guidance and schemas.</p>'''+notice('This release is a <strong>developer preview of named, executable tools</strong>, not a declaration that every instrument family is integrated. The redistribution license and independent release review remain open. <a href="/docs/status.html">Read the exact release scope.</a>')+
'<div class="doc-grid">'+card('Make one promise.','Create an intention and explicit criteria, then retain its exact words.','/docs/quickstart.html','01 / BEGIN')+card('Keep the original.','Add a sourced correction without erasing what came first.','/docs/records.html','02 / PRESERVE')+card('Make scope visible.','Examine purpose, audience, access, and the limits of an authority snapshot.','/docs/boundaries.html','03 / RESPECT')+card('Leave a way back.','Export, interrupt, restore, and compare the work—not just a success message.','/docs/continuity.html','04 / RETURN')+'</div><h2>Refactoring for Kindness.</h2><p>The Human Stewardship Guidelines give this practice its human obligations. They are not a badge added after implementation. They shape preparation, attention, context, review, and the ability to leave and return.</p><a class="button" href="/docs/human-stewardship.html">Read the Human Stewardship Guidelines →</a><h2>Try it before integrating.</h2><p>The browser lab uses the same local SDK file provided in the download. It makes an original, appends a correction, checks a refusal, and restores a recovery archive. Its results are limited to that example; they are not a fabricated production certification.</p><a class="button secondary" href="/playground.html">Open the working example →</a>')
quick='''import { PromiseStep, RecordBook } from 'promisestep-sdk';

const promise = PromiseStep.promise({
  name: 'Better onboarding',
  intention: 'Let a person pause without losing their work.'
});
const book = new RecordBook();
await book.record({
  operationId: 'capture-1', recordId: promise.id,
  kind: 'promise', author: 'example-developer',
  payload: { intention: promise.intention }
});
const backup = await book.export();
const restored = await RecordBook.restore(JSON.stringify(backup));
console.log(await restored.get(promise.id));'''
articles['quickstart.html']=('A first working step.','A small, inspectable example. No account, API key, or private upload required.',
'<h2>1. Try the browser example.</h2><p>Begin with the <a href="/playground.html">correction and recovery lab</a>. It uses sample text in page memory, not a remote account. Export the example before leaving to keep it.</p><h2>2. Inspect the source preview.</h2><p>The JavaScript package works in Node.js 20+ and modern secure browsers. It has zero runtime dependencies and includes TypeScript declarations. This download is a source preview; the final open-source distribution license has not yet been selected. It is <strong>not published to npm</strong>.</p><div class="lab-actions"><a class="button" href="/downloads/promisestep-sdk-'+V+'.tgz" download>Download JavaScript / TypeScript</a><a class="button secondary" href="/downloads/promisestep-sdk-'+V+'-source.zip" download>Download source & tests</a></div><p class="source-caption"><a href="/downloads/SHA256SUMS.txt">Check download digests</a> · <a href="/sdk/v'+V+'/LICENSE-STATUS.txt">Distribution standing</a> · <a href="/sdk/v'+V+'/index.d.ts">TypeScript reference</a></p>'+code('npm install ./promisestep-sdk-'+V+'.tgz','install')+'<h2>3. Create and restore a local record.</h2><p>Save this as <code>first-step.mjs</code> and run <code>node first-step.mjs</code>. A successful return gives the original payload back; it does not publish it.</p>'+code(quick,'first-example')+'<h2>4. Keep your application’s own authority.</h2><p>The SDK works with caller-controlled data. Your application still owns authentication, persistence, retention, and enforcement at the actual read or write boundary. A local snapshot check never grants access to a protected service.</p><h2>Other languages.</h2><p>The versioned HTTP reference API can be read with any HTTP client. A dependency-free <a href="/downloads/promisestep-python-reference-client.zip" download>Python reference client</a> is included separately. It is an HTTP client, not a claim of full JavaScript-core parity. Java, Swift, and other full bindings are not part of this release.</p>'+code("from promisestep import PublicAPIClient\nprint(PublicAPIClient().get('guidelines')['title'])",'python-example')+'<h2>When the network is unavailable.</h2><p>All local-core functions remain usable. Only an explicitly created <code>PublicAPIClient</code> makes network calls. Use the saved package and <a href="/docs/continuity.html">test an offline restoration</a>.</p>')
articles['records.html']=('The original keeps its place.','Records and corrections preserve what was said without silently changing its standing.',
'<h2>Append; do not erase.</h2><p><code>RecordBook</code> is an in-memory event history. An original has a stable record ID, an attributed author, a declared kind, source references, and a payload. A correction has a reason and the revision it intends to correct. Both remain inspectable.</p>'+code('''const original = await book.record({
  operationId: 'record-1', recordId: 'work-1', kind: 'report',
  author: 'example-participant', sourceRefs: ['source:one'],
  payload: { text: 'The words as originally recorded.' }
});
await book.correct({
  operationId: 'correction-1', recordId: 'work-1',
  expectedRevision: original.revision,
  reason: 'Correct the quoted wording from the source.',
  author: 'example-participant', sourceRefs: ['source:correction'],
  payload: { text: 'The corrected wording.' }
});
console.log(await book.history('work-1'));''')+'<h2>Three deliberate safeguards.</h2><p><strong>Revision checks:</strong> a stale correction returns <code>REVISION_CONFLICT</code>, preserving the accepted revision. <strong>Idempotency:</strong> an identical operation ID and input returns the existing event; changed input with that ID returns <code>IDEMPOTENCY_CONFLICT</code>. <strong>Standing:</strong> a report stays a report after a correction. It does not become a finding.</p><h2>What a receipt does not establish.</h2><p>A local record can preserve a reported event or an attributed receipt. It does not prove delivery, acknowledgment, assent, nonpayment, or a legal finding. Keep those as separate, sourced events. An absent receipt is not proof of what did not happen.</p><h2>Storage is explicit.</h2><p>The class does not write to a database, browser storage, or a remote service. Use your own authorized persistence adapter or an exported archive. Never treat a success in page memory as durable storage.</p>'+notice('Names and source references are supplied attribution, not verified identities. A digest establishes byte consistency relative to that digest, not truthful authorship.'))
articles['boundaries.html']=('Permission keeps its scope.','The intended action, purpose, audience, and authority must meet at the same boundary.',
'<h2>A local assessment, not an access token.</h2><p><code>assessBoundary</code> compares a request with a supplied grant snapshot. It checks actor, target, action, purpose, audiences, fields, revision, expiry, revocation, and freshness. The owning service must authenticate identity and recheck permission at the point of effect.</p><div class="table-wrap"><table><thead><tr><th>Decision</th><th>Meaning in this toolkit</th></tr></thead><tbody><tr><td>allowed</td><td>The supplied snapshot matches this requested scope. Owner recheck is still required.</td></tr><tr><td>denied</td><td>A known scope or validity condition refuses this action.</td></tr><tr><td>requires_human_review</td><td>A designated human judgment remains required.</td></tr><tr><td>not_yet_determined</td><td>Authority, freshness, or a required revision is unresolved.</td></tr><tr><td>unavailable</td><td>The required owner is unavailable; this is not an allegation or a denial.</td></tr></tbody></table></div><h2>An invitation to listen is not permission to publish.</h2><p>The <a href="/playground.html#scope-example">working example</a> deliberately requests publication against a listen-only grant. The result is a refusal, not an automatic expansion of the invitation.</p><h2>Keep legitimate duties and review.</h2><p>Support, money, relationships, titles, and proximity do not by themselves establish unrelated authority. Actual law, agreements, duties, and emergency procedures still matter within their scope. The SDK does not determine legal capacity, diagnose a person, or remove a legitimate duty of review.</p><h2>Implementation boundary.</h2><p>Do not accept a client’s <code>allowed</code> value as server authorization. Verify the grant issuer, current policy, subject, target, audience, expiry, and revocation at the owning service. This release does not supply an identity provider or a private-record backend.</p>')
articles['continuity.html']=('The work has a way back.','A pause should not become an ending. Recovery should not mean starting over.',
'<h2>Keep a return point.</h2>'+code("const checkpoint = pausePoint({\n  workId: 'work-1', revision: 2,\n  nextAction: 'Review the second verse.',\n  sourceRefs: ['work:version-2']\n});\nconst result = inspectReturn(checkpoint, { workId: 'work-1', revision: 3 });\n// result.state === 'needs_reconciliation'\n// No newer work is overwritten; no access is granted.")+'<h2>Export and actually restore.</h2><p><code>book.export()</code> returns a versioned JSON archive with SHA-256 integrity data. <code>RecordBook.restore()</code> checks the archive, each operation digest, record revisions, correction links, and identity collisions before returning a new book. It does not partially import over an existing book.</p><h2>Optional encrypted archives.</h2>'+code("const archive = await book.export();\nconst encrypted = await encryptArchive(archive, passphrase);\nconst unlocked = await decryptArchive(encrypted, passphrase);\nconst restored = await RecordBook.restore(unlocked);",'encrypted')+'<p>The optional local envelope uses AES-256-GCM, a fresh 12-byte nonce and 16-byte salt, and PBKDF2-SHA256 with 600,000 iterations. The passphrase is not retained. This is not a substitute for a security review, safe key custody, or an independent backup. There is no password-reset service for these local encrypted files.</p><h2>What remains your application’s responsibility.</h2><p>Retain the export in an appropriate location, protect access, test restoration with the actual artifacts, and recheck current permissions before resuming an action. Restoring an old copy must not resurrect revoked access. A same-provider alternate hostname is not independent disaster recovery.</p>'+notice('Unencrypted checksums do not authenticate an attacker-controlled archive: an attacker who can replace both the content and its digest can create a new self-consistent file. Preserve authenticated custody or use an appropriate authenticated encryption workflow.')+'<h2>A concrete recovery exercise.</h2><p>In the lab, create a record, add a correction, export, clear the in-memory working copy, restore, and inspect both revisions. Then modify the exported payload without updating its digest and confirm that import is refused. The original working copy remains intact when import fails.</p>')
articles['journeys.html']=('A completed step is not a kept promise.','Inspect the experience, the release, and the evidence—not only a green status.',
'<h2>Declare an observable promise.</h2><p>A promise keeps its original intention and criteria. Observations name that promise, its revision, the criterion, the release, their source evidence, and the time of observation. Reported experiences remain valid reports without being silently converted into independently observed facts.</p><h2>Inspect a bounded outcome.</h2>'+code("const result = assessJourney(promise, observations, { release: 'my-app-1.2.0' });\nconsole.log(result.state, result.checks, result.excludedObservationIds);")+'<p>The local assessment can return <code>evidenced_for_scope</code>, <code>unmet_for_scope</code>, <code>requires_human_review</code>, or <code>not_yet_determined</code>. It does not independently authenticate the supplied observations or certify the complete human experience. One unresolved critical obligation is not cancelled by many favorable observations.</p><h2>Inspect more than the happy path.</h2><p>Arrival, orientation, waiting, empty states, interruption, refusal, failure, preservation, recovery, return, sharing, support, service delivery, and post-release experience each deserve a deliberate check. Preserve separately offered human accounts; do not infer a person’s emotion from telemetry.</p><h2>Keep review distinct.</h2><p>The canonical Human Stewardship review has its own questions and outcomes. It cannot be concluded by a model generating a reviewer’s name or by passing this function. <a href="/docs/human-stewardship.html#review">Read the review method.</a></p>')
articles['songwriter.html']=('Let the song keep its beginning.','Version lineage, attributed contributions, and invitations that do not silently change control.',
'<h2>Local song lineage.</h2><p><code>SongGraph</code> preserves a composition’s supplied version relationships. Parents must already exist and belong to the same song. A version ID cannot be quietly reused for different material. Contributor references are assertions of attribution, not an ownership finding.</p>'+code("const graph = new SongGraph();\ngraph.addVersion({\n  id: 'version-1', songId: 'song-1', parentIds: [],\n  assetDigest: recordingSHA256,\n  contributorRefs: ['contributor:one'], sourceRefs: ['recording:original']\n});\nconsole.log(graph.snapshot());")+'<h2>Where a song is observed.</h2><p>A location record includes a URL, a source, an observation time, and whether it was reported or observed. The local graph does not crawl the internet or monitor platforms. Absence from the graph means no supplied observation—not absence from the internet.</p><h2>Invite without transferring authorship.</h2><p><code>draftSongInvite</code> prepares listen, comment, or submit-contribution scopes for specific versions. It does not send the invitation, authenticate the inviter, grant access, declare acceptance, transfer ownership, or publish the song.</p><h2>The larger song ecosystem.</h2><p>SongGit lineage, SongDev resources, Song Invite delivery, SongGraph discovery, SongSketch integration, and the Center for the Song remain distinct family integrations. This release supplies the named local primitives; it does not declare those entire owning services integrated.</p>')
articles['localization.html']=('Language changes. Meaning needs care.','Keep the original, its context, and the review path beside every translated edition.',
'<h2>Preserve the source.</h2><p><code>reviewLocalization</code> retains the original and candidate with a source ID, revision, and locales. It checks placeholder identities and counts, and explicitly protected terms. It never silently replaces the source.</p>'+code("const review = reviewLocalization({\n  sourceId: 'welcome', sourceRevision: 1,\n  sourceLocale: 'en-US', targetLocale: 'es-MX',\n  sourceText: 'Welcome, {name}.',\n  candidateText: 'Hola, {name}.'\n});\n// No missing placeholders: still requires human meaning review.")+'<h2>A syntax match is not a trustworthy translation.</h2><p>A candidate without structural issues still returns <code>requires_human_review</code>. The function does not translate text, judge cultural suitability, certify legal equivalence, or change permissions. A translation provider and an appropriate human review route are separate integrations.</p><h2>Keep consequential meanings stable.</h2><p>Promises, conditions, attribution, access boundaries, and governing instructions need source-linked review. A later correction remains an attributed revision. Dates, numbers, pluralization, right-to-left layouts, accessible names, and local conventions require application-level tests beyond the placeholder check.</p>')
principles=''.join(f'<section id="{H(p["id"])}"><p class="eyebrow">FOUNDATION {i+1:02d}</p><h2>{H(p["title"])}</h2><blockquote>{H(p["statement"])}</blockquote><p><strong>In practice:</strong> {H(p["practice"])}</p><p class="source-id">{H(p["id"])}</p></section>' for i,p in enumerate(GUIDELINES['principles']))
articles['human-stewardship.html']=('Human Stewardship Guidelines.','The principles behind software that respects people, preserves meaning, and leaves a way to continue.',
'<p class="source-caption">Developer reference · 2 November 2026 · Canonical Volume I principles and review questions. The source records ratification on 13 July 2026. Application notes below are explanatory, not amendments.</p><h2>Stewardship is responsibility, not unrestricted authority.</h2><p>These guidelines describe what the work owes to the people it touches. Human attention, context, dignity, judgment, and continuity belong in the design of an experience—not only in its introduction.</p>'+notice('This is official PromiseStep developer documentation of the recovered source. It is <strong>not a new ratification, a legal instrument, or certification</strong> that this SDK or every integration already conforms. A passing structural check never replaces accountable human review.')+principles+'<h2 id="review">The ten review questions.</h2><ol>'+''.join(f'<li>{H(q)}</li>' for q in GUIDELINES['reviewQuestions'])+'</ol><p>A concluded review needs a named, accountable human reviewer and source-linked findings. Preparation, dispatch, or the presence of a review record does not establish that the review occurred.</p><p><strong>Review outcomes:</strong> '+', '.join(GUIDELINES['reviewOutcomes'])+'. These are not the API execution decisions <code>allowed</code>, <code>denied</code>, or <code>unavailable</code>. Keep the two meanings separate.</p><h2 id="execution">From principle to execution.</h2><p>Every family adapter needs a source-bound execution path. The following stages are the implementation guide; they do not replace the original standards or supply missing authority.</p><ol>'+''.join(f'<li>{H(s)}.</li>' for s in GUIDELINES['executionStages'])+'</ol><h2>The wider guideline collection.</h2><p>Recovered source records identify five ratified volumes: Foundations of Human Stewardship, The Steward, Hospitality, Human Attention, and Human Understanding. This page publishes Volume I’s ten principles and the review method, with an overview of the wider collection. It does not substitute planned future volumes for adopted content.</p><p><strong>The Steward:</strong> care for understanding is not ownership or control. <strong>Hospitality:</strong> prepare conditions for a person to participate before asking them to arrive. <strong>Human Attention:</strong> purpose, pacing, silence, and departure matter. <strong>Human Understanding:</strong> information alone is not understanding; questions and human judgment remain protected.</p><h2>Source, corrections, and application limits.</h2><p>The principle IDs above remain the original IDs. The source revision and digest are recorded in the <a href="/api/v1/guidelines">machine-readable reference</a>. Preserve exact source wording when creating an application guide. Publish an attributed correction rather than silently rewriting the source or claiming a new adoption.</p><p>In this release, <code>prepareStewardshipReview</code> creates an un-concluded preparation with these ten questions. The SDK does not commission a human, pronounce agreement, rank people, or manufacture constitutional completion.</p><p><a href="/downloads/human-stewardship-guidelines.json" download>Save this reference for offline use →</a></p>')
articles['api.html']=('A public reference API.','Versioned guidance and contracts. Private work stays in your application.',
'<h2>Read it from any development environment.</h2>'+code('curl --fail https://promisestep.com/api/v1/guidelines','curl')+'<p>This initial HTTP surface is <strong>read-only</strong>. It serves public reference material, not a copy of anyone’s private records. No account or API key is needed. Do not submit song drafts, personal evidence, credentials, or case records in URLs or request bodies.</p><div class="table-wrap"><table><thead><tr><th>GET resource</th><th>Returns</th></tr></thead><tbody><tr><td><a href="/api/v1/health">/api/v1/health</a></td><td>This reference service and release identity; not the health of all connected products.</td></tr><tr><td><a href="/api/v1/guidelines">/api/v1/guidelines</a></td><td>Source-backed Human Stewardship reference.</td></tr><tr><td><a href="/api/v1/capabilities">/api/v1/capabilities</a></td><td>Named local capabilities and their explicit limits.</td></tr><tr><td><a href="/api/v1/schemas">/api/v1/schemas</a></td><td>Versioned public data schemas.</td></tr><tr><td><a href="/api/v1/release">/api/v1/release</a></td><td>Package identity and release scope.</td></tr><tr><td><a href="/api/v1/openapi.json">/api/v1/openapi.json</a></td><td>OpenAPI description of this exact read-only surface.</td></tr></tbody></table></div><h2>Predictable failures.</h2><p>Unknown resources and API versions return JSON <code>404</code>, not an HTML application fallback. Mutation methods return <code>405</code> with an <code>Allow</code> header. Query parameters return <code>400</code>; this reference service does not accept private inputs. GET and HEAD support entity tags, and OPTIONS documents the permitted methods. CORS does not allow credentials.</p><h2>Individual family contracts.</h2><p>Each recovered family has its own reference boundary at <code>/api/v1/contracts/{slug}</code>. A reference resource describes a family; it is not an implementation of that family’s private owner service. <a href="/docs/status.html#families">Browse the full scope and exact integration status.</a></p><h2>Client behavior.</h2>'+code("const client = new PublicAPIClient();\nconst controller = new AbortController();\nconst guidelines = await client.get('guidelines', { signal: controller.signal });",'client')+'<p>The JavaScript client has bounded timeouts, cancellation, JSON validation, response-size limits, no credential forwarding, and no redirect following. Network unavailability is distinct from refusal. The Python client provides the same read-only resource allowlist and bounded response handling.</p>')
status_intro='''<h2>Implemented in this developer preview.</h2><p>Local promises; attributed originals and corrections; revision and idempotency checks; integrity-checked export and restore; optional encrypted archives; explicit boundary-snapshot assessment; scoped journey-evidence assessment; pause/return points; local song lineage and observed locations; unsent scoped song invitations; localization structural review; stewardship review preparation; JavaScript/TypeScript and Python public-reference clients; the versioned read-only reference API.</p><h2>Not claimed as complete.</h2><p>The full instrument body, authenticated owner-service integrations, remote private-record operations, song internet discovery, invitation delivery, full natural-language translation, complete language-binding parity, independent security review, human stewardship consensus, and constitutional completion are not established by this release. A named contract is not evidence of an implemented integration.</p><h2>Open release gates.</h2><p>The founder’s specific open-source distribution license remains to be recorded. The requested dedicated public GitHub repository is not yet verified. No npm or PyPI registry release is claimed. The public source preview does not license private infrastructure or private records.</p><h2 id="families">The larger instrument scope.</h2><p>The family inventory below carries the recovered names and purpose boundaries. It is not an instrument count, a replacement canonical registry, or an assertion that the historically reported 475 Dependents’ Rights instruments are reconciled.</p><label for="contract-search">Find a family</label><input type="search" id="contract-search" data-contract-filter placeholder="For example, Living Record, Heard, or SongGraph"><p class="search-count" data-search-count aria-live="polite"></p>'''
# The private research pack is not distributed. This exact public-only snapshot
# was reconstructed from the verified 62 contract references in the released API.
# Rebuild must not fabricate a different family inventory if this source is lost.
source=R/'developer/family-reference-snapshot.json'
families=[]
references=json.loads(source.read_text())
if len(references)!=62 or len({c['name'] for c in references})!=62:
 raise ValueError('The verified public contract inventory is incomplete; refusing to alter the release')
for c in references:
 slug=re.sub('[^a-z0-9]+','-',c['name'].lower()).strip('-')
 public={'slug':slug,'name':c['name'],'purpose':c['purpose'],'accessBoundary':c['access_boundaries'],'guidelineReference':'/api/v1/guidelines','referenceStanding':'architecture-reference','ownerAdapterStatus':'not_verified_in_this_release','notices':['A contract reference is not an operational owner-service integration.','Local tools do not confer authority, legal effect, or access to private records.']}
 families.append(public)
family_html=''.join('<details data-contract-item><summary>'+H(c['name'])+'</summary><p>'+H(c['purpose'])+'</p><p><strong>Boundary:</strong> '+H(c['accessBoundary'])+'</p><p class="status-chip">Owner adapter: not verified in this release</p><p><a href="/api/v1/contracts/'+c['slug']+'">Read this family reference →</a></p></details>' for c in families)
articles['status.html']=('Release scope, without guesswork.','What this package does, what the public service serves, and what still needs its own evidence.',status_intro+'<div class="contract-collection">'+family_html+'</div><h2>Verification belongs to the actual source.</h2><p>The release manifest binds the downloadable package to its digest. Tests for this source are retained separately from earlier historical reports. A local test, deployment, successful server response, browser interaction, and human review each establish different things.</p><p><a href="/api/v1/release">Read the current release manifest →</a></p>')
for key,(title,description,body) in articles.items(): (PUB/key).write_text(page(title,description,body,key))
lab='''<p>This lab runs the same local SDK offered in the source download. It does not send your work to a server, save it automatically, or create private-record access.</p><div data-sdk-lab><section class="lab-panel"><h2>One promise. A working record.</h2><label for="intention">The original intention</label><textarea id="intention" data-lab-intention rows="3" maxlength="2000">Make it easier to pause and return without losing the original work.</textarea><div class="lab-actions"><button type="button" class="button" data-lab-create>Create a local example</button><button type="button" class="button secondary" data-lab-reset>Clear this example</button></div><p class="lab-status" data-lab-status role="status" aria-live="polite">Start with the sample text. There is no account and no remote save.</p></section><section class="lab-panel"><h2>Correct without erasing.</h2><label for="correction">The corrected wording</label><textarea id="correction" data-lab-correction rows="3" maxlength="2000">Keep the original wording and the reason for every correction, so returning is possible.</textarea><div class="lab-actions"><button type="button" class="button secondary" data-lab-correct disabled>Append a correction</button></div><p data-lab-empty>No local record yet.</p><ol class="lab-history" data-lab-history aria-label="Original and correction history"></ol></section><section class="lab-panel"><h2>Pause. Recover. Compare.</h2><p>Export before leaving. The interruption exercise clears the working copy while retaining an archive in this page’s memory. A downloaded file is the way to carry it outside this session.</p><div class="lab-actions"><button type="button" class="button" data-lab-export disabled>Export recovery file</button><button type="button" class="button secondary" data-lab-interrupt disabled>Clear the working copy</button><button type="button" class="button secondary" data-lab-restore disabled>Restore archive</button></div><label for="restore-file">Or restore your downloaded example</label><input id="restore-file" type="file" accept=".json,application/json" data-lab-file><div class="lab-actions"><button type="button" class="button secondary" data-lab-check disabled>Check the original survived</button></div><pre class="lab-code" data-lab-result aria-label="Scoped evidence assessment"></pre></section><section class="lab-panel" id="scope-example"><h2>An invitation is not unlimited permission.</h2><p>This supplied example grant permits listening. Try to publish with it: the local scope check must refuse.</p><div class="lab-actions"><button type="button" class="button secondary" data-lab-boundary>Try publication with listen-only scope</button></div><p class="lab-result" data-boundary-result aria-live="polite"></p></section></div><h2>Use it in your own application.</h2><p>Keep your existing storage, identity provider, and service ownership. The local toolkit helps prepare, preserve, and inspect the work. Your owning services enforce their actual authority and boundaries.</p><a href="/docs/quickstart.html" class="button">Get the source preview →</a>'''
(R/'playground.html').write_text(page('A working example.','Create an original. Make a correction. Test a refusal. Take the work with you.',lab,'playground','TRY THE LOCAL SDK'))
