def add_tar(t,arc,data):
 info=tarfile.TarInfo(arc);info.size=len(data);info.mtime=0;info.mode=0o644;t.addfile(info,io.BytesIO(data))
tar_buffer=io.BytesIO()
with tarfile.open(fileobj=tar_buffer,mode='w') as t:
 for p in sorted((R/'sdk/js').iterdir()):
  if p.is_file():add_tar(t,'package/'+p.name,p.read_bytes())
(DOWN/f'promisestep-sdk-{V}.tgz').write_bytes(gzip.compress(tar_buffer.getvalue(),compresslevel=9,mtime=0))
def zip_add(z,name,data):
 info=zipfile.ZipInfo(name,(2026,11,2,0,0,0));info.compress_type=zipfile.ZIP_DEFLATED;info.external_attr=0o644 << 16;z.writestr(info,data)
with zipfile.ZipFile(DOWN/f'promisestep-sdk-{V}-source.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted((R/'sdk').rglob('*')):
  if p.is_file() and p.suffix in ('.mjs','.mts','.ts','.py','.md','.txt','.json'): zip_add(z,'sdk/'+str(p.relative_to(R/'sdk')),p.read_bytes())
 zip_add(z,'developer/api-handler.mjs',(R/'developer/api-handler.mjs').read_bytes())
 zip_add(z,'package.json', '{"type":"module","private":true,"license":"UNLICENSED"}\n')
 zip_add(z,'README.txt','PromiseStep source preview. Run: node --test sdk/tests/*.test.mjs. Run the example: node sdk/js/example.mjs. No dependency install needed for core. See sdk/js/LICENSE-STATUS.txt.\n')
with zipfile.ZipFile(DOWN/'promisestep-python-reference-client.zip','w',zipfile.ZIP_DEFLATED) as z:
 zip_add(z,'promisestep.py',(R/'sdk/python/promisestep.py').read_bytes());zip_add(z,'LICENSE-STATUS.txt',(R/'sdk/js/LICENSE-STATUS.txt').read_bytes())
 zip_add(z,'README.txt','Python 3.10+. Put promisestep.py beside your code and import PublicAPIClient. Reads only public reference resources; no private records or writes, no full JavaScript-core parity claimed.\n')
