# Reference schemas describe this release, not unimplemented owner-side services.
def obj(props,required=None):return {'type':'object','properties':props,'required':required or list(props),'additionalProperties':False}
string={'type':'string'};identifier={'type':'string','pattern':'^[A-Za-z0-9][A-Za-z0-9._:/-]*$','maxLength':160};sources={'type':'array','items':{'type':'string'},'uniqueItems':True,'maxItems':128}
schemas={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'https://promisestep.com/api/v1/schemas','title':'PromiseStep public local-core data schemas','release':RELEASE,'$defs':{}}
schemas['$defs']['Criterion']=obj({'id':identifier,'description':{'type':'string','minLength':1},'requiresHumanReview':{'type':'boolean'}},['id','description'])
schemas['$defs']['PromiseInput']=obj({'id':identifier,'name':{'type':'string','minLength':1,'maxLength':200},'intention':{'type':'string','minLength':1,'maxLength':8192},'criteria':{'type':'array','items':{'$ref':'#/$defs/Criterion'},'maxItems':128},'sourceRefs':sources,'extensions':{}},['name','intention'])
schemas['$defs']['Archive']=obj({'format':{'const':'promisestep/archive'},'formatVersion':{'const':1},'algorithm':{'const':'SHA-256'},'digest':{'type':'string','pattern':'^[0-9a-f]{64}$'},'payload':{}})
schemas['$defs']['BoundaryRequest']=obj({'actor':string,'target':string,'action':string,'purpose':string,'audience':{'type':'array','items':string,'minItems':1,'uniqueItems':True},'fields':{'type':'array','items':string,'minItems':1,'uniqueItems':True},'expectedGrantRevision':{'type':'integer','minimum':1},'requiresHumanReview':{'type':'boolean'}},['actor','target','action','purpose','audience','fields','expectedGrantRevision'])
schemas['$defs']['LocalizationInput']=obj({'sourceId':identifier,'sourceRevision':{'type':'integer','minimum':1},'sourceText':string,'candidateText':string,'sourceLocale':string,'targetLocale':string,'protectedTerms':sources},['sourceId','sourceRevision','sourceText','candidateText','sourceLocale','targetLocale'])
features=[('promises',['createPromise','PromiseStep.promise'],'Local exact intention and criteria; fulfillment not automatically inferred.'),('records',['RecordBook'],'Local originals, corrections, idempotency and revision checks; persistence chosen by the application.'),('boundaries',['assessBoundary'],'Supplied-snapshot assessment only; owner authentication and enforcement remain required.'),('continuity',['createArchive','readArchive','encryptArchive','decryptArchive','pausePoint','inspectReturn'],'Local integrity, optional encryption and non-destructive return checks; retained backups remain the operator’s responsibility.'),('journeys',['assessJourney'],'Scoped supplied-evidence assessment, not independent certification.'),('songwriter',['SongGraph','draftSongInvite'],'Local lineage, attributed locations, and unsent invitations; no discovery crawler or delivery service.'),('localization',['reviewLocalization'],'Source/placeholder/term review; no translation engine or automatic meaning verification.'),('human-stewardship',['prepareStewardshipReview'],'Preparation with canonical questions, not a concluded human review.'),('public-reference-client',['PublicAPIClient'],'Read-only transport; no private write operations.')]
capabilities={'release':RELEASE,'sdkVersion':V,'scope':'local-core-and-public-reference-api','capabilities':[{'name':n,'exports':ex,'execution':'local' if n!='public-reference-client' else 'explicit-network-read','boundary':b} for n,ex,b in features],'ownerIntegrations':'not_verified_in_this_release','familyInventoryIsNotAnInstrumentCount':True,'licenseStatus':'founder_license_selection_pending'}
release={'id':RELEASE,'sdkVersion':V,'standing':'developer-preview','siteTitle':'A developer’s toolkit for practical possibilities.','guidelineEdition':GUIDELINES['edition'],'publicAPIMode':'read-only-reference','privateRecordWrites':False,'registryPublication':False,'licenseStatus':'founder_license_selection_pending','sourcePackage':'/downloads/promisestep-sdk-'+V+'-source.zip','package':'/downloads/promisestep-sdk-'+V+'.tgz','integrity':'/downloads/SHA256SUMS.txt','localOnlyFunctions':True,'independentReview':'not_completed','completeInstrumentCollection':'not_claimed'}
resources={'/api/v1/health':{'service':'promisestep-public-reference','release':RELEASE,'status':'ok','scope':'this-read-only-reference-service','privateRecords':False},'/api/v1/guidelines':GUIDELINES,'/api/v1/capabilities':capabilities,'/api/v1/schemas':schemas,'/api/v1/release':release}
